# ── N0 ── AIC + 엔드포인트 타입 검사
library(yaml)

check_n0_aic <- function(aic_path,
                        types_requiring_endpoint = c(
                          "AIC-PKPD", "AIC-ER", "AIC-TTE", "AIC-BIOMARKER",
                          "AIC-CELL_THERAPY", "AIC-IMMUNOGEN", "AIC-LACTATION"
                        )) {
  # 1) AIC 파일 존재 확인
  if (!file.exists(aic_path)) {
    return(list(pass = FALSE, q_code = "Q11",
                reason = "AIC YAML이 데이터 패키지에 없음"))
  }
  aic <- yaml::read_yaml(aic_path)

  # 2) type 필드 자체 존재 확인
  if (is.null(aic$type)) {
    return(list(pass = FALSE, q_code = "Q11",
                reason = "AIC$type 누락"))
  }

  # 3) endpoint_data_type 필요 여부
  if (aic$type %in% types_requiring_endpoint &&
      is.null(aic$endpoint_data_type)) {
    return(list(pass = FALSE, q_code = "Q11",
                reason = sprintf(
                  "AIC type=%s 에는 endpoint_data_type 선언 필수",
                  aic$type)))
  }

  list(pass = TRUE, aic = aic)
}

