# ── N1 ── 환자 식별자 검사
library(dplyr)

check_n1_id <- function(df, aic) {
  # 1) ID 컬럼 후보 탐색
  id_candidates <- c("USUBJID", "SUBJID", "ID", "SUBJECT")
  id_col <- intersect(id_candidates, names(df))[1]
  if (is.na(id_col)) {
    return(list(pass = FALSE, q_code = "Q03",
                reason = sprintf("ID 컬럼 후보 %s 모두 없음",
                                 paste(id_candidates, collapse="/"))))
  }

  # 2) 결측 검사
  if (any(is.na(df[[id_col]]))) {
    return(list(pass = FALSE, q_code = "Q03",
                reason = "ID 컬럼에 NA 존재"))
  }

  # 3) 모자 연결 — LACTATION/MATERNAL_INFANT_PK
  if (aic$type == "AIC-LACTATION" || 
      isTRUE(aic$endpoint_data_type %in% c("MATERNAL_INFANT_PK", "MILK_PK"))) {
    if (is.null(aic$dyad_linkage_policy)) {
      return(list(pass = FALSE, q_code = "Q18",
                  reason = "MATERNAL_INFANT_PK인데 dyad_linkage_policy 누락"))
    }
    if (!"DYAD_KEY" %in% names(df)) {
      return(list(pass = FALSE, q_code = "Q18",
                  reason = "DYAD_KEY 컬럼 없음"))
    }
  }

  list(pass = TRUE, id_col = id_col)
}

