# ── N3 ── 용량 기록 검사
check_n3_dose <- function(df, aic) {
  if (!"AMT" %in% names(df) && !"DOSE" %in% names(df)) {
    return(list(pass = FALSE, q_code = "Q08",
                reason = "AMT/DOSE 컬럼 없음"))
  }
  amt_col <- if ("AMT" %in% names(df)) "AMT" else "DOSE"

  dose_rows <- df %>% filter(EVID == 1)
  if (any(is.na(dose_rows[[amt_col]]))) {
    return(list(pass = FALSE, q_code = "Q08",
                reason = "투여 이벤트 행에 AMT=NA 존재"))
  }

  # 재구성 필요 케이스 — 정책 검사
  needs_policy <- list(
    weight = "reconstruct_dose_weight_policy",
    bsa    = "reconstruct_dose_bsa_policy",
    titr   = "reconstruct_dose_titration_policy",
    inf    = "infusion_reconstruction_policy",
    addl   = "addl_actual_conflict_policy"
  )
  if (isTRUE(aic$dose_type == "WEIGHT_BASED") &&
      is.null(aic[[needs_policy$weight]])) {
    return(list(pass = FALSE, q_code = "Q08",
                reason = "체중 기반 용량인데 reconstruct_dose_weight_policy 누락"))
  }
  # (BSA, titration, infusion, addl_conflict 동일 패턴)

  list(pass = TRUE, amt_col = amt_col)
}

