N4.r_code_check:
# ── N4 ── 관측치/구획 검사
check_n4_obs_cmt <- function(df, aic) {
  if (!"DV" %in% names(df) && !"CONC" %in% names(df)) {
    return(list(pass = FALSE, q_code = "Q09",
                reason = "DV/CONC 컬럼 없음"))
  }
  # BLQ/LLOQ 정책
  if (any(df$BLQ == 1, na.rm = TRUE) && is.null(aic$blq_handling_policy)) {
    return(list(pass = FALSE, q_code = "Q01",
                reason = "BLQ 행 있지만 blq_handling_policy 누락"))
  }
  if (is.null(aic$lloq) && any(df$BLQ == 1, na.rm = TRUE)) {
    return(list(pass = FALSE, q_code = "Q01",
                reason = "LLOQ 값 누락"))
  }
  # cellular kinetics
  if (isTRUE(aic$endpoint_data_type == "CELLULAR_KINETICS")) {
    if (is.null(aic$cellular_LLOQ_derivation_policy)) {
      return(list(pass = FALSE, q_code = "Q01",
                  reason = "세포 동태학인데 cellular_LLOQ_derivation_policy 누락"))
    }
  }
  # immunogenicity
  if (isTRUE(aic$endpoint_data_type == "IMMUNOGENICITY")) {
    if (is.null(aic$positivity_adjudication_rule)) {
      return(list(pass = FALSE, q_code = "Q19",
                  reason = "면역원성인데 positivity_adjudication_rule 누락"))
    }
  }
  # multi-analyte → analyte_role
  multi_modality <- aic$modality_class %in% c("ADC","BISPECIFIC","CELL_THERAPY")
  if (multi_modality && is.null(aic$analyte_role_policy)) {
    return(list(pass = FALSE, q_code = "Q16",
                reason = sprintf("%s — analyte_role_policy 누락",
                                 aic$modality_class)))
  }
  list(pass = TRUE)
}

