# ── N5 ── BLQ 정책 적용 가능?
check_n5_blq <- function(df, aic) {
  n_blq <- sum(df$BLQ == 1, na.rm = TRUE)
  if (n_blq == 0) return(list(pass = TRUE, n_blq = 0))

  policy <- aic$blq_handling_policy
  if (is.null(policy) || !policy %in% c("M1","M3","M4","M5","M6","exclude","project_specific")) {
    return(list(pass = FALSE, q_code = "Q01",
                reason = sprintf("BLQ %d행 — 정책=%s (지원 안 함)",
                                 n_blq, policy %||% "NULL")))
  }
  if (is.null(aic$lloq)) {
    return(list(pass = FALSE, q_code = "Q01",
                reason = "LLOQ 값 누락"))
  }
  list(pass = TRUE, policy = policy, lloq = aic$lloq, n_blq = n_blq)
}

