  df <- switch(n5$policy,
    "M1" = df %>% filter(!(BLQ == 1 & EVID == 0)),  # BLQ 행 제외
    "M3" = df %>% mutate(
             DV  = if_else(BLQ == 1 & EVID == 0, n5$lloq, DV),
             MDV = if_else(BLQ == 1 & EVID == 0, 0L, 0L)  # M3: likelihood, MDV=0
           ),
