# ── N8 ── action_sequence별 필요 정책 검사
check_n8_policy_bundle <- function(action_sequence, aic, function_library) {
  required_policies <- action_sequence %>%
    purrr::map(~ function_library[[.x]]$required_policy) %>%
    unlist() %>% unique()
  declared <- names(aic)
  missing <- setdiff(required_policies, declared)
  if (length(missing) > 0) {
    return(list(pass = FALSE, q_code = "Q15A",
                reason = sprintf("필요 정책 누락: %s",
                                 paste(missing, collapse = ", "))))
  }
  list(pass = TRUE)
}

