convert_units.r_code:
convert_units <- function(df, unit_map) {
  # unit_map: list(DV = list(from = "ng/mL", to = "mg/L", factor = 1e-3))
  for (col in names(unit_map)) {
    spec <- unit_map[[col]]
    df[[col]] <- df[[col]] * spec$factor
  }
  df
}

map_subject_id.r_code:
map_subject_id <- function(df, id_col = "USUBJID", policy = "sequential") {
  if (policy == "sequential") {
    df <- df %>%
      mutate(ID = as.integer(factor(.data[[id_col]],
                                    levels = unique(.data[[id_col]]))))
  } else if (policy == "study_offset") {
    df <- df %>%
      group_by(STUDY) %>%
      mutate(ID_local = as.integer(factor(.data[[id_col]]))) %>%
      ungroup() %>%
      mutate(ID = ID_local + STUDY_OFFSET[STUDY])
  }
  df %>% relocate(ID, .before = everything())
}

