derive_time_postpartum_anchor <- function(df, delivery_anchor) {
  # delivery_anchor: 환자별 분만 datetime
  df %>%
    left_join(delivery_anchor, by = "ID") %>%
    mutate(
      .t = lubridate::ymd_hms(ATIME),
      TIME_POSTPARTUM = as.numeric(difftime(.t, delivery_time, units = "days"))
    ) %>%
    select(-.t)
}

