reconstruct_dose_bsa.r_code:
reconstruct_dose_bsa <- function(df) {
  df %>%
    mutate(
      BSA = if_else(is.na(BSA), sqrt(WT * HT / 3600), BSA),  # Mosteller
      AMT = if_else(
        EVID == 1 & DOSE_TYPE == "BSA_BASED",
        DOSE_PER_BSA * BSA,
        AMT
      )
    )
}

canonicalize_blq.r_code:
canonicalize_blq <- function(df, policy = c("M1","M3","M4"), lloq) {
  policy <- match.arg(policy)
  switch(policy,
    "M1" = df %>% filter(!(BLQ == 1 & EVID == 0)),
    "M3" = df %>%
      mutate(
        DV  = if_else(BLQ == 1 & EVID == 0, lloq, DV),
        MDV = if_else(BLQ == 1 & EVID == 0, 0L, MDV)
      ),
    "M4" = df %>%
      mutate(
        DV  = if_else(BLQ == 1 & EVID == 0, lloq / 2, DV),
        MDV = if_else(BLQ == 1 & EVID == 0, 0L, MDV)
      )
  )
}

canonicalize_cellular_blq.r_code:
canonicalize_cellular_blq <- function(df, sample_volume_mL = 1) {
  lloq_cell <- 1 / sample_volume_mL
  df %>%
    mutate(
      BLQ_CELL = if_else(DV < lloq_cell, 1L, 0L),
      DV       = if_else(BLQ_CELL == 1 & EVID == 0, lloq_cell, DV),
      MDV      = if_else(BLQ_CELL == 1 & EVID == 0, 0L, MDV)
    )
}

assign_evid.r_code:
assign_evid <- function(df) {
  df %>%
    mutate(EVID = case_when(
      !is.na(AMT) & AMT > 0           ~ 1L,  # 투여
      !is.na(DV) & is.na(AMT)         ~ 0L,  # 관측
      RESET_FLAG == 1                 ~ 3L,  # 리셋
      TRUE                            ~ 2L   # 기타
    ))
}

