attach_covariate_time_varying.r_code:
attach_covariate_time_varying <- function(df, cov_df, method = c("locf","linear")) {
  method <- match.arg(method)
  joined <- df %>%
    left_join(cov_df, by = c("ID", "TIME"))
  if (method == "locf") {
    joined %>% group_by(ID) %>% tidyr::fill(WT, AGE, .direction = "down") %>% ungroup()
  } else {
    joined %>% group_by(ID) %>%
      mutate(across(c(WT, AGE), ~ zoo::na.approx(.x, x = TIME, na.rm = FALSE))) %>%
      ungroup()
  }
}

