attach_dyad_linkage.r_code:
attach_dyad_linkage <- function(df, dyad_map) {
  # dyad_map: tibble(MOTHER_ID, INFANT_ID, DYAD_KEY)
  df %>% left_join(
    bind_rows(
      dyad_map %>% select(ID = MOTHER_ID, DYAD_KEY) %>% mutate(ROLE = "MOTHER"),
      dyad_map %>% select(ID = INFANT_ID, DYAD_KEY) %>% mutate(ROLE = "INFANT")
    ),
    by = "ID"
  )
}

